insert into public.courses
  (id, slug, name, level, level_name, step, summary, pathway_summary, outline, gains,
   formats, prereq_slug, fee_minor, fee_currency, fee_note, upcoming, "order")
values
  (
    '2300b8a2-6797-43c2-8919-6d6db3c690b9',
    'grace-reset',
    'Grace Reset',
    '01',
    'Foundations',
    'Level One · Start here',
    '{"en":"Level One of Grace Academy. Eight classes that ground you in the foundational truths of the gospel of the grace of Christ and carry you out of legalism, from the works of the law and the works of the flesh into the fruit of the Spirit. Anchored in Hebrews 13:9a.","de":"Stufe Eins der Grace Academy. Acht Klassen, die dich in den grundlegenden Wahrheiten des Evangeliums der Gnade Christi verwurzeln und dich aus der Gesetzlichkeit herausführen, von den Werken des Gesetzes und den Werken des Fleisches hinein in die Frucht des Geistes. Verankert in Hebräer 13,9a.","nl":"Niveau Een van Grace Academy. Acht lessen die je gronden in de fundamentele waarheden van het evangelie van de genade van Christus en je uit het wetticisme leiden, van de werken van de wet en de werken van het vlees naar de vrucht van de Geest. Verankerd in Hebreeën 13:9a.","fr":"Niveau Un de Grace Academy. Huit cours qui vous enracinent dans les vérités fondamentales de l''évangile de la grâce du Christ et vous font sortir du légalisme, des œuvres de la loi et des œuvres de la chair vers le fruit de l''Esprit. Ancré dans Hébreux 13:9a."}'::jsonb,
    '{"en":"Eight classes that ground you in the gospel of the grace of Christ and move you out of legalism, from the works of the law into the fruit of the Spirit.","de":"Acht Klassen, die dich im Evangelium der Gnade Christi verwurzeln und dich aus der Gesetzlichkeit herausführen, von den Werken des Gesetzes hinein in die Frucht des Geistes.","nl":"Acht lessen die je gronden in het evangelie van de genade van Christus en je uit het wetticisme leiden, van de werken van de wet naar de vrucht van de Geest.","fr":"Huit cours qui vous enracinent dans l''évangile de la grâce du Christ et vous font sortir du légalisme, des œuvres de la loi vers le fruit de l''Esprit."}'::jsonb,
    '[{"title":"Forgiveness of sin and righteousness by faith","body":{"en":"How forgiveness actually works under the new covenant, and why righteousness is received rather than earned.","de":"Wie Vergebung im neuen Bund wirklich wirkt, und warum Gerechtigkeit empfangen und nicht verdient wird.","nl":"Hoe vergeving werkelijk werkt onder het nieuwe verbond, en waarom gerechtigheid ontvangen wordt en niet verdiend.","fr":"Comment le pardon fonctionne réellement sous la nouvelle alliance, et pourquoi la justice se reçoit au lieu de se mériter."},"scripture":"Romans 3:21-24; 2 Corinthians 5:21"},{"title":"Eternal salvation and new creation reality","body":{"en":"The security of your salvation, and what it means to be a new creation in Christ.","de":"Die Sicherheit deiner Errettung, und was es bedeutet, eine neue Schöpfung in Christus zu sein.","nl":"De zekerheid van je redding, en wat het betekent om een nieuwe schepping in Christus te zijn.","fr":"La sécurité de votre salut, et ce que signifie être une nouvelle création en Christ."},"scripture":"John 10:28-29; 2 Corinthians 5:17"},{"title":"The place of good works in God''s kingdom","body":{"en":"Resolving the tension between grace and works, with Ephesians 2 read in full context.","de":"Die Spannung zwischen Gnade und Werken auflösen, mit Epheser 2 im vollen Zusammenhang gelesen.","nl":"De spanning tussen genade en werken oplossen, met Efeziërs 2 in de volledige context gelezen.","fr":"Résoudre la tension entre la grâce et les œuvres, avec Éphésiens 2 lu dans son contexte complet."},"scripture":"Ephesians 2:8-10; Titus 2:11-14"},{"title":"The baptism of the Holy Spirit","body":{"en":"Ten reasons why you should pray in tongues, with the baptism of the Holy Spirit ministered to you.","de":"Zehn Gründe, warum du in Zungen beten solltest, und die Taufe im Heiligen Geist wird dir zuteil.","nl":"Tien redenen waarom je in tongen zou moeten bidden, en de doop met de Heilige Geest wordt aan je bediend.","fr":"Dix raisons de prier en langues, avec le baptême du Saint-Esprit qui vous sera administré."},"scripture":"Luke 24:45-49; Acts 1:4-8; 8:14-17; 19:1-7"},{"title":"Prayer and devotion practice week","body":{"en":"A set-aside week to build the habit: twenty minutes praying in tongues and twenty minutes in the Word, every day.","de":"Eine eigens reservierte Woche, um die Gewohnheit aufzubauen: jeden Tag zwanzig Minuten in Zungen beten und zwanzig Minuten im Wort.","nl":"Een apart gezette week om de gewoonte op te bouwen: elke dag twintig minuten in tongen bidden en twintig minuten in het Woord.","fr":"Une semaine mise à part pour ancrer l''habitude : vingt minutes de prière en langues et vingt minutes dans la Parole, chaque jour."},"special":true},{"title":"The purpose of knowing the eternal nature of salvation","body":{"en":"Why this assurance is given to you in the first place, read through the elder brother in Luke 15.","de":"Warum dir diese Gewissheit überhaupt gegeben ist, gelesen durch den älteren Bruder in Lukas 15.","nl":"Waarom deze zekerheid je in de eerste plaats gegeven is, gelezen door de oudste broer in Lucas 15.","fr":"Pourquoi cette assurance vous est donnée au départ, lue à travers le frère aîné en Luc 15."},"scripture":"Luke 15:25-32"},{"title":"Three main perversions of the gospel","body":{"en":"What distorts the gospel, how to recognise twisted doctrine, and how to respond to it.","de":"Was das Evangelium verzerrt, wie du verdrehte Lehre erkennst, und wie du darauf antwortest.","nl":"Wat het evangelie verdraait, hoe je verwrongen leer herkent, en hoe je erop reageert.","fr":"Ce qui déforme l''évangile, comment reconnaître une doctrine faussée, et comment y répondre."},"scripture":"Galatians 1:6-9; 2 Corinthians 11:3-4"},{"title":"Special sermons on evangelism","body":{"en":"How to share the gospel, and the food of Jesus we should all know about.","de":"Wie du das Evangelium weitergibst, und die Speise Jesu, die wir alle kennen sollten.","nl":"Hoe je het evangelie deelt, en het voedsel van Jezus dat we allemaal zouden moeten kennen.","fr":"Comment annoncer l''évangile, et la nourriture de Jésus que nous devrions tous connaître."},"scripture":"John 4","special":true},{"title":"How to live a holy life","body":{"en":"Roll away the stone. The ministry of the Holy Spirit is God''s permanent replacement for the stone of the law and for the odour it covered.","de":"Wälze den Stein weg. Der Dienst des Heiligen Geistes ist Gottes dauerhafter Ersatz für den Stein des Gesetzes und für den Geruch, den er verdeckte.","nl":"Rol de steen weg. De bediening van de Heilige Geest is Gods blijvende vervanging voor de steen van de wet en voor de geur die hij bedekte.","fr":"Roulez la pierre. Le ministère du Saint-Esprit est le remplacement permanent que Dieu donne à la pierre de la loi et à l''odeur qu''elle recouvrait."},"scripture":"John 11; Romans 8:1-4"},{"title":"Day out: share the good news","body":{"en":"A practical evangelism outing together, taken straight after the teaching on holy living.","de":"Ein gemeinsamer praktischer Evangelisationseinsatz, direkt im Anschluss an die Lehre über ein heiliges Leben.","nl":"Een praktische evangelisatie-uitstap samen, direct na het onderwijs over heilig leven.","fr":"Une sortie d''évangélisation pratique ensemble, juste après l''enseignement sur la vie sainte."},"special":true},{"title":"Four factors for living a holy life","body":{"en":"The four pillars that sustain holy living under grace, so freedom never becomes an excuse.","de":"Die vier Säulen, die ein heiliges Leben unter der Gnade tragen, damit Freiheit nie zur Ausrede wird.","nl":"De vier pijlers die heilig leven onder genade dragen, zodat vrijheid nooit een excuus wordt.","fr":"Les quatre piliers qui soutiennent une vie sainte sous la grâce, pour que la liberté ne devienne jamais une excuse."},"scripture":"Titus 2:11-12; Romans 6:11-14"},{"title":"Meeting with graduating students","body":{"en":"Embracing discipleship culture, an overview of the AGBC discipleship system, and prayer as you step into the internship phase.","de":"Die Jüngerschaftskultur annehmen, ein Überblick über das AGBC-Jüngerschaftssystem, und Gebet für deinen Schritt in die Praktikumsphase.","nl":"Discipelschapscultuur omarmen, een overzicht van het AGBC-discipelschapssysteem, en gebed terwijl je de stagefase ingaat.","fr":"Adopter la culture de formation de disciples, un aperçu du système de disciples de l''AGBC, et la prière au moment d''entrer dans la phase de stage."},"special":true}]'::jsonb,
    '[{"en":"Settled assurance that your sins are forgiven and that righteousness is received, not earned","de":"Feste Gewissheit, dass deine Sünden vergeben sind und dass Gerechtigkeit empfangen und nicht verdient wird","nl":"Vaste zekerheid dat je zonden vergeven zijn en dat gerechtigheid ontvangen wordt, niet verdiend","fr":"L''assurance établie que vos péchés sont pardonnés et que la justice se reçoit et ne se mérite pas"},{"en":"Freedom from legalism, with a clear answer on where good works belong","de":"Freiheit von Gesetzlichkeit, mit einer klaren Antwort darauf, wo gute Werke hingehören","nl":"Vrijheid van wetticisme, met een helder antwoord op waar goede werken thuishoren","fr":"La liberté face au légalisme, avec une réponse claire sur la place des bonnes œuvres"},{"en":"The baptism of the Holy Spirit, and ten reasons to pray in tongues every day","de":"Die Taufe im Heiligen Geist, und zehn Gründe, jeden Tag in Zungen zu beten","nl":"De doop met de Heilige Geest, en tien redenen om elke dag in tongen te bidden","fr":"Le baptême du Saint-Esprit, et dix raisons de prier en langues chaque jour"},{"en":"The ability to recognise a perverted gospel and answer it from Scripture","de":"Die Fähigkeit, ein verdrehtes Evangelium zu erkennen und ihm aus der Schrift zu begegnen","nl":"Het vermogen om een verdraaid evangelie te herkennen en het vanuit de Schrift te beantwoorden","fr":"La capacité de reconnaître un évangile perverti et d''y répondre par les Écritures"},{"en":"A daily rhythm of prayer and the Word that outlasts the course","de":"Ein täglicher Rhythmus aus Gebet und Wort, der über den Kurs hinaus bleibt","nl":"Een dagelijks ritme van gebed en het Woord dat de cursus overleeft","fr":"Un rythme quotidien de prière et de Parole qui dure au-delà du cours"},{"en":"Practical experience sharing the gospel on a supervised day out","de":"Praktische Erfahrung im Weitergeben des Evangeliums bei einem begleiteten Einsatztag","nl":"Praktische ervaring in het delen van het evangelie tijdens een begeleide uitstapdag","fr":"Une expérience pratique de l''annonce de l''évangile lors d''une sortie encadrée"},{"en":"Four pillars for living a holy life under grace","de":"Vier Säulen für ein heiliges Leben unter der Gnade","nl":"Vier pijlers voor een heilig leven onder genade","fr":"Quatre piliers pour vivre une vie sainte sous la grâce"},{"en":"A place in the AGBC discipleship system and a clear step into Grace Masterclass","de":"Ein Platz im AGBC-Jüngerschaftssystem und ein klarer Schritt in die Grace Masterclass","nl":"Een plaats in het AGBC-discipelschapssysteem en een duidelijke stap naar de Grace Masterclass","fr":"Une place dans le système de disciples de l''AGBC et une étape claire vers la Grace Masterclass"},{"en":"A certificate of completion","de":"Ein Abschlusszertifikat","nl":"Een certificaat van afronding","fr":"Un certificat de fin de formation"}]'::jsonb,
    '{"intensive":{"en":"2 weeks","de":"2 Wochen","nl":"2 weken","fr":"2 semaines"},"part_time":{"en":"4 weeks","de":"4 Wochen","nl":"4 weken","fr":"4 semaines"}}'::jsonb,
    null,
    2500,
    'GBP',
    '{"en":"workbook included","de":"Arbeitsbuch inbegriffen","nl":"werkboek inbegrepen","fr":"manuel inclus"}'::jsonb,
    false,
